<template><section class="container section"><div class="section-heading"><div><p class="eyebrow">Личный кабинет</p><h1>Мои бронирования</h1></div><RouterLink class="btn btn-clay" to="/">Найти ресторан</RouterLink></div><div v-if="$route.query.created" class="alert alert-success" role="status">Учебная бронь создана.</div><StatusPanel v-if="loading">Загружаем бронирования…</StatusPanel><StatusPanel v-else-if="error" kind="error">{{ error }} <button class="link-button" @click="load">Повторить</button></StatusPanel><div v-else-if="!bookings.length" class="empty-state"><h2>Пока нет бронирований</h2><p>Выберите ресторан и создайте первую учебную бронь.</p></div><div v-else class="booking-list"><article v-for="booking in bookings" :key="booking.id" class="booking-item"><div class="booking-head"><div><p class="eyebrow">{{ restaurants[booking.restaurantId]?.name || 'Ресторан' }}</p><h2>{{ booking.date }} · {{ booking.time }}</h2><p>{{ booking.guests }} {{ plural(booking.guests) }}<span v-if="booking.comment"> · {{ booking.comment }}</span></p></div><span class="booking-status">Активна</span></div><div class="booking-actions"><button class="btn btn-soft" @click="toggleEdit(booking)">{{ editing === booking.id ? 'Закрыть' : 'Изменить' }}</button><button class="btn btn-outline-danger" :disabled="removing===booking.id" @click="cancel(booking)">{{ removing===booking.id?'Отменяем…':'Отменить' }}</button></div><BookingForm v-if="editing===booking.id" :initial="booking" :busy="saving===booking.id" :error="formError" submit-label="Сохранить изменения" @submit="update(booking.id,$event)" /></article></div></section></template><script setup>import { onMounted, ref } from 'vue'; import BookingForm from '../components/BookingForm.vue'; import StatusPanel from '../components/StatusPanel.vue'; import { bookingApi,restaurantApi } from '../composables/useApi'; const bookings=ref([]),restaurants=ref({}),loading=ref(true),error=ref(''),editing=ref(''),saving=ref(''),removing=ref(''),formError=ref('');const plural=(number)=>number===1?'гость':number<5?'гостя':'гостей';async function load(){loading.value=true;error.value='';try{const [items,list]=await Promise.all([bookingApi.list(),restaurantApi.list()]);bookings.value=items;restaurants.value=Object.fromEntries(list.map((x)=>[x.id,x]));}catch(e){error.value=e.message;}finally{loading.value=false;}}function toggleEdit(booking){editing.value=editing.value===booking.id?'':booking.id;formError.value='';}async function update(id,payload){saving.value=id;formError.value='';try{const changed=await bookingApi.update(id,payload);bookings.value=bookings.value.map((x)=>x.id===id?changed:x);editing.value='';}catch(e){formError.value=e.message;}finally{saving.value='';}}async function cancel(booking){if(!window.confirm('Отменить эту учебную бронь?'))return;removing.value=booking.id;try{await bookingApi.remove(booking.id);bookings.value=bookings.value.filter((x)=>x.id!==booking.id);}catch(e){error.value=e.message;}finally{removing.value='';}}onMounted(load);</script>
